#!/bin/bash
# usage: run.sh <label main|bump> <corpus name> <srcdir> <run#>
label=$1; name=$2; src=$3; n=$4
out=/tmp/claude-501/tsrs-spike/out
cd "$src" || exit 9
/usr/bin/time -l /tmp/claude-501/tsrs-spike/bin/$label-docgen extract --src . --quiet --no-cache --load-dependencies --json -vv \
  > $out/$name.$label.$n.json 2> $out/$name.$label.$n.err
f=$out/$name.$label.$n.err
read r u s <<<"$(awk '/ real .* user .* sys/{print $1,$3,$5}' $f)"
rss=$(awk '/maximum resident/{print $1}' $f)
reqs=$(grep -a 'semantic component answered' $f | sed 's/\x1b\[[0-9;]*m//g' | grep -o 'requests=[0-9]*' | cut -d= -f2 | paste -sd+ - | bc)
ncomp=$(grep -a -c 'semantic component answered' $f)
bad=$(python3 -I - "$out/$name.$label.$n.json" <<'EOF'
import json,sys
d=json.load(open(sys.argv[1]))
def walk(x,acc):
    if isinstance(x,dict):
        if x.get('code')=='SEMANTIC_BACKEND': acc.append(x.get('severity'))
        for v in x.values(): walk(v,acc)
    elif isinstance(x,list):
        for v in x: walk(v,acc)
acc=[]; walk(d,acc); print(acc)
EOF
)
echo "$name $label run$n real=$r user=$u sys=$s cpu=$(echo "$u+$s"|bc) rss_mb=$(echo "$rss/1048576"|bc) comps=$ncomp reqs=$reqs semantic_diag=$bad"

